from collections import deque
from itertools import combinations

def compute_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([(start, -1)])
        while queue:
            node, parent = queue.popleft()
            for nb in adj[node]:
                if nb == parent:
                    continue
                if dist[nb] == -1:
                    dist[nb] = dist[node] + 1
                    queue.append((nb, node))
                else:
                    cycle_len = dist[node] + dist[nb] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def all_distances(adj, n):
    dist_matrix = {}
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for nb in adj[node]:
                if dist[nb] == -1:
                    dist[nb] = dist[node] + 1
                    queue.append(nb)
        dist_matrix[start] = dist
    return dist_matrix

def lcf_graph(n, shifts, repeat):
    adj = [set() for _ in range(n)]
    edges = set()
    for i in range(n):
        u, v = i, (i+1) % n
        adj[u].add(v)
        adj[v].add(u)
        edges.add((min(u,v), max(u,v)))
    shift_list = shifts * repeat
    for i in range(n):
        s = shift_list[i % len(shift_list)]
        j = (i + s) % n
        if i != j:
            u, v = min(i,j), max(i,j)
            if (u,v) not in edges:
                adj[u].add(v)
                adj[v].add(u)
                edges.add((u,v))
    return adj, list(edges)

